    return 0;
}

units.explanation:
网格 DFS 是 DFS 在二维数组上的应用。常见于岛屿数量、最大岛屿面积、迷宫可达等问题。

实现要点：
1. 用方向数组 dx[]、dy[] 表示四个方向（上下左右）
2. 检查新位置是否越界（0 <= nx < n, 0 <= ny < m）
3. 检查新位置是否可走/未访问

方向数组：
int dx[] = {-1, 1, 0, 0};  // 上、下、左、右
int dy[] = {0, 0, -1, 1};

网格 DFS 模板：
void dfs(int x, int y) {
    visited[x][y] = true;
    for (int d = 0; d < 4; d++) {
        int nx = x + dx[d], ny = y + dy[d];
        if (合法且未访问) dfs(nx, ny);
    }
}

常见题型：
- 岛屿数量：对每个未访问的陆地起点做 DFS，DFS 调用次数 = 岛屿数
- 最大岛屿面积：在 DFS 中计数
- 迷宫可达：从起点 DFS，检查终点是否被访问

units.exampleCode:
#include <iostream>
using namespace std;

int n, m;
char grid[100][100];
bool visited[100][100];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void dfs(int x, int y) {
    visited[x][y] = true;
    for (int d = 0; d < 4; d++) {
        int nx = x + dx[d], ny = y + dy[d];
        if (nx >= 0 && nx < n && ny >= 0 && ny < m
            && !visited[nx][ny] && grid[nx][ny] == '1') {
            dfs(nx, ny);
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> grid[i][j];
    int cnt = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (grid[i][j] == '1' && !visited[i][j]) {
                dfs(i, j);
                cnt++;
            }
    cout << cnt << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

vector<int> adj[100];
bool visited[100];

int treeDepth(int u, int parent) {
    int maxDepth = 0;
    for (int v : adj[u]) {
        if (v != parent) {
            maxDepth = max(maxDepth, treeDepth(v, u));
        }
    }
    return maxDepth + 1;
}

int subtreeSize(int u, int parent) {
    int size = 1;
    for (int v : adj[u]) {
        if (v != parent) {
            size += subtreeSize(v, u);
        }
    }
    return size;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    cout << "Tree depth: " << treeDepth(1, -1) << endl;
    cout << "Subtree size of 1: " << subtreeSize(1, -1) << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> adj[100];
bool visited[100];
int dist[100];

void bfs(int start) {
    queue<int> q;
    q.push(start);
    visited[start] = true;
    dist[start] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    bfs(1);
    for (int i = 1; i <= n; i++)
        cout << i << ": " << dist[i] << endl;
    return 0;
}

units.explanation:
回溯法是「试错」的搜索方法：尝试每种可能，发现走不通就回退（撤销选择），换另一条路。

回溯框架：
void backtrack(状态) {
    if (满足结束条件) { 记录答案; return; }
    for (每个候选选择) {
        做选择;
        backtrack(新状态);
        撤销选择;  // 回溯
    }
}

DFS 遍历 vs 回溯枚举：
- DFS 遍历：访问图中所有节点，每个节点只访问一次，不撤销状态
- 回溯枚举：在解空间中搜索所有可能的解，需要撤销选择来尝试其他方案

回溯三步曲：
1. 做选择：修改当前状态（如 path.push_back(i)）
2. 递归：backtrack(新状态)
3. 撤销选择：恢复状态（如 path.pop_back()）

常见问题：子集、组合、排列、N皇后。

units.exampleCode:
#include <iostream>
#include <vector>
using namespace std;

int n;
vector<int> path;

void backtrack(int used) {
    if (path.size() == n) {
        for (int x : path) cout << x << " ";
        cout << endl;
        return;
    }
    for (int i = 1; i <= n; i++) {
        if (used & (1 << i)) continue;
        path.push_back(i);
        backtrack(used | (1 << i));
        path.pop_back();
    }
}

int main() {
    cin >> n;
    backtrack(0);
    return 0;
}

units.explanation:
剪枝是在搜索过程中提前判断某些分支不可能产生正确答案，直接跳过，减少搜索量。

常见剪枝策略：

1. 可行性剪枝：当前状态已经不满足约束，直接 return
   if (当前和 > target) return;

2. 最优性剪枝：当前方案不可能比已知最优更好，直接 return
   if (当前代价 >= best) return;

3. 排序剪枝：先将候选按某种顺序排列，配合剪枝更高效
   sort(candidates.begin(), candidates.end());
   如果最小的都超了，后面更大的更超，直接 break

4. 去重剪枝：避免生成重复的方案
   if (i > start && candidates[i] == candidates[i-1]) continue;

剪枝的核心思想：宁可多剪一点时间，也不要漏掉正确答案。剪枝条件必须保守——宁可不过关，不能误杀。

常见错误：剪枝条件过强导致漏解。例如把 >= 写成 >，把不该剪的分支也剪掉了。

units.exampleCode:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> candidates;
vector<vector<int>> results;
vector<int> path;
int target;

void dfs(int start, int remain) {
    if (remain == 0) {
        results.push_back(path);
        return;
    }
    for (int i = start; i < (int)candidates.size(); i++) {
        if (candidates[i] > remain) break;
        if (i > start && candidates[i] == candidates[i - 1]) continue;
        path.push_back(candidates[i]);
        dfs(i + 1, remain - candidates[i]);
        path.pop_back();
    }
}

int main() {
    int n;
    cin >> n >> target;
    candidates.resize(n);
    for (int i = 0; i < n; i++) cin >> candidates[i];
    sort(candidates.begin(), candidates.end());
    dfs(0, target);
    for (auto& r : results) {
        for (int x : r) cout << x << " ";
        cout << endl;
    }
    return 0;
}

#include <iostream>
#include <cstring>
using namespace std;

int memo[50];

int fib(int n) {
    if (n <= 1) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = fib(n - 1) + fib(n - 2);
}

int climbStairs(int n) {
    if (n <= 2) return n;
    if (memo[n] != -1) return memo[n];
    return memo[n] = climbStairs(n - 1) + climbStairs(n - 2);
}

int main() {
    memset(memo, -1, sizeof(memo));
    cout << "fib(10) = " << fib(10) << endl;
    memset(memo, -1, sizeof(memo));
    cout << "climbStairs(10) = " << climbStairs(10) << endl;
    return 0;
}
